using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{public static int Run(string folder){var j=new JavaScriptSerializer();var data=new Dictionary<string,object>();IZDoc d=null;bool pass=false;try{var r=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;string copy=Path.Combine(folder,"probe.ics");File.Copy((string)r["source"],copy,false);bool already;d=app.OpenFile2(copy,true,false,out already);var part=(IZPart)((IZSceneDocUtility)d).GetElementById(Convert.ToInt32(r["node_id"]));var body=part.GetBody(true);data["type"]=body.BodyType.ToString();data["faces"]=body.GetFacesCount();data["faceIds"]=body.GetFaceIds();data["bounds"]=body.GetBoundingBox();data["suppressed"]=((IZElement)part).GetStateStatus(eZElementState.Z_SUPPRESSED);data["hidden"]=part.IsHidden;
try{object raw;((IZFacetPart)part).GetPolyMeshes(out raw);data["facet_raw_type"]=raw==null?"null":raw.GetType().FullName;if(raw is Array)data["facet_meshes"]=((Array)raw).Length;}catch(Exception e){data["facet_error"]=e.Message;}
var ids=body.GetFaceIds() as Array;if(ids!=null&&ids.Length>0){try{var mesh=((IZBodyFace)body).CopyPolyMesh(Convert.ToInt32(ids.GetValue(0)));data["face_mesh_vertices"]=mesh.VertexCount;data["face_mesh_facets"]=mesh.FacetCount;}catch(Exception e){data["face_mesh_error"]=e.Message;}}pass=true;}catch(Exception e){data["error"]=e.ToString();}finally{if(d!=null)d.Close2(true);}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(new{passed=pass,data=data}));return pass?0:1;}}}
